effect.shader:
void main() {
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
float span = max(whiteIn - blackIn, 0.0001);
vec3 t = clamp((src.rgb - vec3(blackIn)) / span, vec3(0.0), vec3(1.0));
t = pow(t, vec3(1.0 / max(gamma, 0.001)));
vec3 outRgb = vec3(blackOut) + (vec3(whiteOut) - vec3(blackOut)) * t;
gl_FragColor = vec4(clamp(outRgb, vec3(0.0), vec3(1.0)), src.a);
}
